/* L17_winograd.c -- forward complex-double 3D DFT of the 17^3 cube.
 *
 * TECHNIQUE
 *   A hand-derived 17-point module obtained from the Fermat-prime structure of
 *   17 = 2^4+1, applied along all three axes by a three-pass row-column sweep
 *   whose passes each rotate the index order so that every pass reads and
 *   writes with unit-stride SIMD lanes.
 *
 *   Derivation (verified numerically, rel err 7e-16, see the strategy record):
 *     * (Z/17)* is cyclic of order 16, generated by g = 3.  Rader turns the
 *       17-point DFT into a length-16 cyclic convolution.
 *     * Quotienting by {+-1} splits that convolution canonically as
 *          Z[x]/(x^16-1) = Z[x]/(x^8-1)  (+)  Z[x]/(x^8+1),
 *       i.e. u_j = x_j + x_(17-j) drives a length-8 CYCLIC correlation with the
 *       REAL kernel c_r = cos(2 pi 3^r/17), and v_j = x_j - x_(17-j) drives a
 *       length-8 NEGACYCLIC correlation with the imaginary kernel i*sin(...).
 *       Indexing j and k by the order-8 quotient group makes both matrices
 *       (skew-)circulant -- checked exactly, err 2.4e-15.
 *     * The cyclic half splits ONE more level with sign-only reductions:
 *          x^8-1 = (x^4-1)(x^4+1),
 *       P_m = u_m + u_(m+4), Q_m = u_m - u_(m+4), giving a 4x4 cyclic and a 4x4
 *       negacyclic apply instead of one 8x8.  That is the whole win: 64 -> 32
 *       real MACs per component.  x^8+1 is irreducible over R, so the
 *       negacyclic half is left dense (see the record for why every way of
 *       splitting it -- Winograd cyclotomic, sqrt(2) factorisation, x^4-+i --
 *       loses on instruction count).
 *
 * LAYOUT / SIMD  (the other half of the technique)
 *   Each pass transforms the OUTER index of a [17][289] array and stores its
 *   result with the index order rotated left by one:
 *       in [x][y][z] --P1--> A[y][z][kx] --P2--> B[z][kx][ky] --P3--> out[kx][ky][kz]
 *   so the axis being transformed is always the outer one (stride SP) and the
 *   289-long "spectator" pair is always contiguous.  The SIMD lanes hold W
 *   consecutive spectators, so every lane runs the same straight-line code with
 *   lane-invariant broadcast constants and zero cross-lane traffic inside the
 *   kernel.  289 = 36*8 + 1 = 72*4 + 1, so exactly ONE spectator per pass falls
 *   outside the vector groups; it is (q,r) = (16,16) and is done by a scalar
 *   instantiation of the same kernel -- no masking, no padding-lane waste, and
 *   no out-of-bounds read at the end of the batch.
 *   The rotation is paid for inside the store: the kernel's 17 output vectors
 *   (indexed by output index, lanes = old spectator) are turned into W runs of
 *   17 contiguous doubles (lane-major) by W*log2(W) two-source shuffles per
 *   WxW block -- 24 vpermt2pd/vshuff64x2/vunpckpd per block at W=8.  Those land
 *   on port 5 while the FMAs are on port 0/1, so on a 1-FMA-unit part they are
 *   free; the W lanes' destinations are contiguous, so the stores stream.
 *   Scratch is 2 x (split re,im) x 17 x SP doubles = 161 kB, L2-resident, and
 *   is independent of the batch: B=1 and B=large run the identical code path.
 *
 * OPERATION COUNT PER 17-POINT TRANSFORM (exact; counted in the emitted
 * assembly, not estimated -- gcc -O3 -march=native emits exactly 296 FP
 * instructions per kernel instance):
 *     192 FMA + 104 add/sub = 296 FP instructions, 488 flops.
 *   Comparison on the same accounting (docs/literature/02 sections 2.4-2.7):
 *     this module                     296 instr / 488 flops
 *     FFTW dft-generic-17 (dense)     336 instr / 592 flops
 *     Rader-17, two length-16 FFTs    388 instr / 468 flops
 *     Winograd/WFTA-17 (Burrus T7.1)  384 instr / 384 flops (70 mul+314 add)
 *   The dense kernel is built into this file too (-DL17_DENSE_KERNEL) and
 *   measured 39.4 us against this module's 32.3 us per 17^3 transform in an
 *   otherwise identical harness (Haswell, AVX2, B=1): -18%.
 *   The minimum-multiplication WFTA route LOSES here and is not used; see the
 *   strategy record for the counts that kill each way of splitting the
 *   negacyclic half.
 *   Per 17^3 volume: 3*289*296 = 256,632 FP instructions, 423,096 flops.
 *
 * ASSUMPTIONS
 *   * L == 17 only.  Single-threaded.  Out-of-place, `in` untouched.
 *   * add, mul and FMA all have the same throughput and issue on the same
 *     ports (true for every x86 from Haswell on).  This is what makes the
 *     minimum-multiplication programme lose and the sign-only split win.
 *   * fp-contract is on (-O3 default in gnu11), so `a + b*c` becomes one FMA.
 *   * Twelve instantiations ({256,512}-bit x three kernel schedules, plus two
 *     fused-pass-2+3 variants f4/f8 that delete the full-volume B scratch by
 *     completing passes 2+3 one kx-block at a time out of an L1-resident
 *     mini-buffer, plus two software-pipelined variants p4/p8 that carry the
 *     NEXT volume's pass 1 inside the current volume's fused pass so the input
 *     read is spread across the whole volume's compute, plus two
 *     deferred-transpose variants d8/e8 whose per-group transposed store is
 *     executed one group LATE out of a 4.4 KB staging ping-pong, textually
 *     between the next group's loads and its kernel, so the port-5/store work
 *     sits in the load-latency window under the FMA shadow instead of
 *     serialising after it) are compiled and fft3d_create() picks by
 *     measurement.
 *     On a 1-FMA-unit Cascade Lake part 512-bit and 256-bit code have identical
 *     peak FP throughput while 512-bit pays the AVX-512 licence frequency, so
 *     wider is not automatically faster and guessing is not safe.  All four
 *     execute the same arithmetic in the same order and are bit-identical
 *     (verified by cmp on the output files), so the choice cannot change the
 *     answer -- only the speed.
 */
#define _POSIX_C_SOURCE 200809L
#include <complex.h>
#include <math.h>
#include <stddef.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>

#include "fft3d_api.h"

#define NS 289          /* spectator count per pass: 17*17                  */
#ifndef SP
#define SP 296          /* padded spectator stride, multiple of 8 doubles   */
#endif
#define VOL 4913
#ifdef L17_DENSE_KERNEL
#define NVAR 4
#else
#define NVAR 12        /* {3 kernel schedules} x {256,512 bit} + 2 fused-pass-2+3
                          variants (f4/f8) + 2 cross-volume software-pipelined
                          variants (p4/p8) + 2 deferred-transpose variants
                          (d8/e8), all bit-identical */
#endif

typedef double    v8  __attribute__((vector_size(64)));
typedef double    v8u __attribute__((vector_size(64), aligned(8)));
typedef long long i8v __attribute__((vector_size(64)));
typedef double    v4  __attribute__((vector_size(32)));
typedef double    v4u __attribute__((vector_size(32), aligned(8)));
typedef long long i4v __attribute__((vector_size(32)));

#define BCAST(TY,x) ((TY){0} + (x))   /* scalar -> lane-broadcast, folded at compile time */
#define SH8(a,b,...) ((v8)__builtin_shuffle((v8)(a),(v8)(b),(i8v){__VA_ARGS__}))
#define SH4(a,b,...) ((v4)__builtin_shuffle((v4)(a),(v4)(b),(i4v){__VA_ARGS__}))

#define DEF_K17_A(SUF, T) \
static inline __attribute__((always_inline)) void k17_##SUF(const T *xr, const T *xi, T *yr, T *yi) \
{ \
    T pq[8], vv[16], cc[16]; \
    T a0r, a1r, a2r, a3r, a0i, a1i, a2i, a3i, dr, di, u0r,u0i,u1r,u1i; \
    dr = xr[0]; di = xi[0]; \
    u0r = xr[1] + xr[16];  u0i = xi[1] + xi[16]; \
    u1r = xr[4] + xr[13];  u1i = xi[4] + xi[13]; \
    vv[0] = xr[1] - xr[16];  vv[1] = xi[1] - xi[16]; \
    vv[8] = xr[13] - xr[4];  vv[9] = xi[13] - xi[4]; \
