      a2r = a2r + qr*-4.20101934970526891e-01; \
      a3r = a3r + qr*-3.59700672924310572e-01; \
      a0i = a0i + qi*-8.60991008452280493e-01; \
      a1i = a1i + qi*-1.23791249675178877e-01; \
      a2i = a2i + qi*-4.20101934970526891e-01; \
